css:
:root { --fCd: "Anton", sans-serif; --fEx: "Archivo", sans-serif; --fTh: "Oswald", sans-serif; }
.cd { font-family: var(--fCd); font-weight: 400; text-transform: uppercase; }
.ex { font-family: var(--fEx); font-weight: 900; font-stretch: 125%; text-transform: uppercase; }
.th { font-family: var(--fTh); font-weight: 300; text-transform: uppercase; }
.gr { -webkit-mask-image: var(--distress); mask-image: var(--distress); -webkit-mask-size: 220px 220px; mask-size: 220px 220px; }

.ar { font-family: var(--fEx); font-weight: 900; font-stretch: 100%; text-transform: uppercase; }
